    onshore_tuition_fee = 60240,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '',
    apply_form = 'https://www.murdoch.edu.au/course/Postgraduate/M1279',
    updated_at = NOW()
